/// 这个字符在 `WIDE_CP` 里的下标。
fn wide_idx(ch: char) -> Option<usize> {
    WIDE_CP.binary_search(&(ch as u32)).ok()
}

/// 这个字符占几格。**非 ASCII 一律 2 格**：覆盖集里是汉字与全角符号，
/// 在中文语境下都按双宽排；ASCII 一列一格。
pub fn char_cells(ch: char) -> u64 {
    if (ch as u32) < 0x80 {
        1
    } else {
        2
    }
}

/// 宽字符的**缺失字形**：空心框（边框 + 中间一横）。
/// 它必须与"空格"和"`?`"都不同——前者会把缺失伪装成空、后者会伪装成 ASCII 内容。
fn tofu(bits: &mut [u16; 16]) {
    for (r, row) in bits.iter_mut().enumerate() {
        *row = 0;
        if r == 0 || r == 15 || r == 7 {
            *row = 0xFFFF;
        } else {
            *row = 0x8001;
        }
    }
}

/// 配色取 Windows Terminal 的默认：近黑底（#0C0C0C）+ 浅灰字（#CCCCCC）。
/// 纯黑/纯白看着"生"、对比也过强；这一对与测试图案的三条带仍然都不同 ⇒
/// "画在带上的字"和"带本身"照样分得开（§240 那条对账不受影响）。
pub const FG: u32 = 0x00_CC_CC_CC;
pub const BG: u32 = 0x00_0C_0C_0C;

impl Term {
    /// 按帧缓冲的几何开一块终端。几何小到放不下一个字符时返回 `None`
    /// （不"缩着画"：那会让 `cols` 与夹具算的不一样，红因会变成对账而不是容量）。
    pub fn new(f: &Frame) -> Option<Term> {
        let (w, h, _) = f.geom();
        if w < CELL_W * 8 || h < CELL_H * (BAND_ROWS + 2) {
            return None;
        }
        Some(Self { cols: w / CELL_W, rows: h / CELL_H })
    }

    pub fn dims(&self) -> (u64, u64) {
        (self.cols, self.rows)
    }

    /// 正文区能放几行（冻结带不算）。实时重画用它来定窗口，不在调用方写死分辨率。
    pub fn body_rows(&self) -> usize {
        (self.rows - BAND_ROWS) as usize
    }

    pub fn frozen() -> bool {
        FROZEN.load(Ordering::Acquire)
    }

    /// 把一行位图按 [`SCALE`] 放大成块写出去：`SCALE=2` 时一个字形像素是 2×2 个硬件像素。
    /// 返回 false 表示有点写失败（几何是启动信息给的，越界说明上面哪一步算错了，不能吞）。
    fn blit(&self, f: &Frame, x0: u64, y: u64, bits: u32, width_px: usize) -> bool {
        for c in 0..width_px {
            let on = bits & (1 << (width_px - 1 - c)) != 0;
            let color = if on { FG } else { BG };
            for dy in 0..SCALE {
                for dx in 0..SCALE {
                    if f.put(x0 + c as u64 * SCALE + dx, y + dy, color).is_err() {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// 画一个字符（宽字符占 2 格）。冻结之后是 no-op（返回 false 表示"没画"，调用方可以据此数账）。
    pub fn put_char(&self, f: &Frame, col: u64, row: u64, ch: char) -> bool {
        if Self::frozen() || row >= self.rows || col + char_cells(ch) > self.cols {
            return false;
        }
        let x0 = col * CELL_W;
        let y0 = row * CELL_H;
        match wide_idx(ch) {
            Some(i) => {
                let g = FONT_WIDE[i];
                for r in 0..16u64 {
                    if !self.blit(f, x0, y0 + r * SCALE, g[r as usize] as u32, 16) {
                        return false;
                    }
                }
            }
            None if (ch as u32) >= 0x80 => {
                let mut g = [0u16; 16];
                tofu(&mut g);
                for r in 0..16u64 {
                    if !self.blit(f, x0, y0 + r * SCALE, g[r as usize] as u32, 16) {
                        return false;
                    }
                }
            }
            None => {
                let k = ch as u32;
                let idx = if (0x20..=0x7E).contains(&k) {
                    (k - 0x20) as usize
                } else {
                    (b'?' as u32 - 0x20) as usize     // 控制字符：画 '?'，不当成空白
                };
                let g = FONT_ASCII[idx];
                for r in 0..16u64 {
                    if !self.blit(f, x0, y0 + r * SCALE, g[r as usize] as u32, 8) {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// 整屏刷成背景色。终端模式开屏第一步：把启动阶段画的测试图案（S6a 的红绿蓝三条带）清掉。
    pub fn clear(&self, f: &Frame) {
        for y in 0..self.rows * CELL_H {
            for x in 0..self.cols * CELL_W {
                if f.put(x, y, BG).is_err() {
                    return;
                }
            }
        }
    }

    /// 写一行文本（按字符宽度步进、末尾按格补空格）。返回占用的格数。
    pub fn print_line(&self, f: &Frame, row: u64, s: &str) -> usize {
        if Self::frozen() {
            return 0;
        }
        let mut col = 0u64;
        for ch in s.chars() {
            let w = char_cells(ch);
            if col + w > self.cols {
                break;
            }
            if !self.put_char(f, col, row, ch) {
                return 0;
            }
            col += w;
        }
        // 行尾补空格：不补的话上一行的残留像素会变成"下一行也画对了"的假证人
        while col < self.cols {
            if !self.put_char(f, col, row, ' ') {
                return 0;
            }
            col += 1;
        }
        col as usize
    }

    /// 在正文区（`0 .. rows-BAND_ROWS`）画满确定性内容。返回画了多少行。
    ///
    /// **这里没有滚动**：滚动属于"真镜像日志"那一步（本片还没做），
    /// 现在正文是一次性写完的，所以不需要往上挪。
    pub fn fill_body(&self, f: &Frame) -> u64 {
        let body = self.rows - BAND_ROWS;
        for r in 0..body {
            let mut line = String::new();
            for c in 0..self.cols {
                // 内容由 (行, 列) 唯一决定 ⇒ 宿主机可以原样复算，不需要看内核的脸色
                line.push(char::from(b'A' + (((r * self.cols + c) % 26) as u8)));
            }
            self.print_line(f, r, &line);
        }
        body
    }

    /// 正文区整体上移**一个字符行**（只搬正文区，冻结带不参与）。
    ///
    /// 逐像素搬：`get` 拿原生打包值、`put_raw` 写回去，中间不做任何色彩转换。
    /// 不"只搬最后几行"糊弄——那会让"滚动了"这件事只有日志证人、没有像素证人。
    pub fn scroll_up(&self, f: &Frame) -> bool {
        if Self::frozen() {
            return false;
        }
        let top = 0u64;
        let bottom = (self.rows - BAND_ROWS) * CELL_H;   // 正文区底边（不含冻结带）
        for y in top..bottom - CELL_H {
            for x in 0..self.cols * CELL_W {
                match f.get(x, y + CELL_H) {
                    Ok(v) => { if f.put_raw(x, y, v).is_err() { return false; } }
                    Err(_) => return false,
                }
            }
        }
        // 腾出来的最后一行刷成背景，否则旧内容会在底部留一层"看起来像上一行"的残影
        for y in bottom - CELL_H..bottom {
            for x in 0..self.cols * CELL_W {
                if f.put_raw(x, y, BG).is_err() { return false; }
            }
        }
        true
    }

    /// 滚动一行，再把文本画在正文区最后一行。返回画出的字符格数。
    pub fn print_scrolled(&self, f: &Frame, s: &str) -> usize {
        if Self::frozen() {
            return 0;
        }
        if !self.scroll_up(f) {
            return 0;
        }
        self.print_line(f, self.rows - BAND_ROWS - 1, s)
    }

    /// 落冻结契约：把 [`BAND_TEXT`] 写进底部带，然后**永久闸门**关上。
    /// 返回 (带首行行号, 实际写出的格数)。调用方必须在串口上打一行"已冻结"给宿主机看。
    pub fn freeze_band(&self, f: &Frame) -> (u64, usize) {
        let top = self.rows - BAND_ROWS;
        // 先把带刷成纯背景，免得正文残留混进来让"命中"变成巧合
        for r in top..self.rows {
            self.print_line(f, r, "");
        }
        let mut wrote = 0usize;
        for (i, ch) in BAND_TEXT.chars().enumerate() {
            if i as u64 >= self.cols {
                break;
            }
            // 带还没冻结，所以 print 照常走；闸门在最后一步才关
            if self.put_char(f, i as u64, top, ch) {
                wrote += 1;
            }
        }
        FROZEN.store(true, Ordering::Release);
        (top, wrote)
    }

    /// 冻结带首行的像素左上角（宿主机按同一个数去 PPM 里取样）。
    pub fn band_origin(&self) -> (u64, u64) {
        (0, (self.rows - BAND_ROWS) * CELL_H)
    }
}

// ------------------------------------------------------------------ S6d 实时重画
//
/// **整窗重画**：把环里最后 `max_lines` 条完整行直接刷到正文区第 0.. 行，返回**有内容的行数**。
///
/// 与 [`drain_and_draw`] 的三点差别，每点都是"可重复调用"要求的：
/// 1. 不滚动，按行号直写 ⇒ 第 N 次调用与第 1 次调用画的是同一件事，宿主机可以任意时刻取样；
/// 2. **一个字都不打印**：每轮打一行会把 §245 那套按行序读的判据搅掉（而实时重画一轮都不打才成立）；
/// 3. 没画到的行也刷成空行：`print_line` 行尾补空格 ⇒ 上一帧更靠下的内容不会留下残影当假证人。
pub fn redraw_window(term: &Term, f: &Frame, max_lines: usize) -> usize {
    let n = crate::serial::mirror_len();
    let wrapped = crate::serial::mirror_wrapped();
    let mut total = 1usize;
    for i in 0..n {
        if crate::serial::mirror_byte(i) == 10 {
            total += 1;
        }
    }
    let skip = total.saturating_sub(max_lines);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut idx = 0usize;
    let mut row = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte(i);
        if c == 10 {
            let fragment = wrapped && idx == 0;
            if idx >= skip && !fragment && row < max_lines {
                // 合法 UTF-8 直接按字符画；被截断在多字节字符中间时取**合法前缀**
                // （`valid_up_to`）——只丢掉那半个字，而不是把整行的中文降级成 `?`
                // （用户截图里那串 `??????` 就是这么来的：200 字节上限切断了长中文行）。
                let drew = match core::str::from_utf8(&line[..len]) {
                    Ok(s) => term.print_line(f, row as u64, s),
                    Err(e) => {
                        let ok = e.valid_up_to();
                        term.print_line(f, row as u64, core::str::from_utf8(&line[..ok]).unwrap_or(""))
                    }
                };
                if drew > 0 || len == 0 {
                    row += 1;
                }
            }
            len = 0;
            idx += 1;
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    // 窗口里没被内容占满的行一律刷空：残影像素会被下一帧读成"那行还在"
    while row < max_lines {
        term.print_line(f, row as u64, "");
        row += 1;
    }
    row.min(max_lines)
}

// ------------------------------------------------------------------ S6b-3 消费端
//
/// 把日志环里**最后 `max_lines` 行**逐行滚动画上去，返回 `(窗口行数, 真画上去的行数)`。
///
/// **环住在 `serial`，这里只读** ⇒ 边保持 `display -> diagnostics` 单向，不造新环（§244）。
/// **不许开 `Vec`**：堆上限 `LARGE_MAX = 2048`，一次 8 KiB 的 `with_capacity` 第一下就走
/// `handle_alloc_error` ⇒ 整机 39（ADR-018/026）。所以两遍扫描 + 栈上 200 字节行缓冲，
/// 装满就截断——宁可少画几个字符也要有界。
pub fn drain_and_draw(term: &Term, f: &Frame, max_lines: usize) -> (usize, usize) {
    let n = crate::serial::mirror_len();
    let wrapped = crate::serial::mirror_wrapped();
    // 第一遍：只数换行，不分配、不画图
    let mut total = 1usize;
    for i in 0..n {
        if crate::serial::mirror_byte(i) == 10 {
            total += 1;
        }
    }
    let skip = total.saturating_sub(max_lines);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut idx = 0usize;
    let mut drawn = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte(i);
        if c == 10 {
            // 绕回处那一段是上一行的残片，不是完整日志行：丢掉它，否则画面上是一条半截日志
            let fragment = wrapped && idx == 0;
            if idx >= skip && !fragment {
                // 合法 UTF-8 按字符滚动画上（宽字符占 2 格）；非法则逐字节兜底
                let drew = match core::str::from_utf8(&line[..len]) {
                    Ok(s) => term.print_scrolled(f, s),
                    Err(e) => {
                        let ok = e.valid_up_to();
                        term.print_scrolled(f, core::str::from_utf8(&line[..ok]).unwrap_or(""))
                    }
                };
                // 空行也占一次滚动，否则"画了 N 行"里的空行会谎报成内容行
                if drew > 0 || len == 0 {
                    drawn += 1;
                }
            }
            len = 0;
            idx += 1;
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    (total, drawn)
}

/// 一行最多缓存多少字节。最长一条日志正文实测 **604 字节**（含中文），取 640 留余量。
/// 原来是 200 —— 长中文行被截在半个字中间 ⇒ 整行降级成 `?`（§249 之后用户截图里那串 `??????`）。
const LINE_BUF: usize = 640;

